-- Synthetic local test doubles for Cron, Vault and pg_net interfaces ONLY.
-- No native extensions, encryption, HTTP worker or hosted provider proof.
CREATE SCHEMA cron;CREATE SCHEMA net;CREATE SCHEMA vault;
CREATE TABLE cron.job(jobid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,jobname text UNIQUE,schedule text,command text,database text DEFAULT current_database(),username text DEFAULT current_user,active boolean DEFAULT true);
CREATE TABLE cron.job_run_details(runid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,jobid bigint,end_time timestamptz);
CREATE FUNCTION cron.schedule(job_name text,schedule text,command text) RETURNS bigint LANGUAGE plpgsql AS $$DECLARE id bigint;BEGIN INSERT INTO cron.job(jobname,schedule,command) VALUES(job_name,schedule,command) RETURNING jobid INTO id;RETURN id;END$$;
CREATE FUNCTION cron.alter_job(job_id bigint,schedule text DEFAULT NULL,command text DEFAULT NULL,database text DEFAULT NULL,username text DEFAULT NULL,active boolean DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$BEGIN UPDATE cron.job j SET schedule=coalesce(alter_job.schedule,j.schedule),command=coalesce(alter_job.command,j.command),database=coalesce(alter_job.database,j.database),username=coalesce(alter_job.username,j.username),active=coalesce(alter_job.active,j.active) WHERE jobid=job_id;END$$;
CREATE TABLE vault.secrets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE,decrypted_secret text,updated_at timestamptz DEFAULT clock_timestamp());
CREATE VIEW vault.decrypted_secrets AS SELECT id,name,decrypted_secret,updated_at FROM vault.secrets;
CREATE UNLOGGED TABLE net.http_request_queue(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,method text,url text,headers jsonb,body bytea,timeout_milliseconds integer);
CREATE UNLOGGED TABLE net._http_response(id bigint,status_code integer,content text,timed_out boolean DEFAULT false,error_msg text,created timestamptz DEFAULT clock_timestamp());
CREATE FUNCTION net.http_post(url text,body jsonb DEFAULT '{}'::jsonb,params jsonb DEFAULT '{}'::jsonb,headers jsonb DEFAULT '{"Content-Type":"application/json"}'::jsonb,timeout_milliseconds integer DEFAULT 5000) RETURNS bigint LANGUAGE plpgsql AS $$DECLARE request_id bigint;BEGIN
 INSERT INTO net.http_request_queue(method,url,headers,body,timeout_milliseconds) VALUES('POST',url,headers,convert_to(body::text,'UTF8'),timeout_milliseconds) RETURNING id INTO request_id;
 IF current_setting('collect.test.enqueue_error',true)='true' THEN RAISE EXCEPTION 'synthetic error after queue insertion';END IF;
 RETURN request_id;
END$$;
REVOKE ALL ON SCHEMA cron,net,vault FROM PUBLIC;

-- Explicit provider-reset double. This is not a cluster restart/native worker
-- test: recreate ONLY these synthetic objects to reset their owned sequence
-- and epoch identity while collect_ops logged history remains unchanged.
CREATE FUNCTION net.collect_test_reset_transport() RETURNS void LANGUAGE plpgsql AS $reset$
BEGIN
 DROP TABLE net.http_request_queue,net._http_response;
 CREATE UNLOGGED TABLE net.http_request_queue(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,method text,url text,headers jsonb,body bytea,timeout_milliseconds integer);
 CREATE UNLOGGED TABLE net._http_response(id bigint,status_code integer,content text,timed_out boolean DEFAULT false,error_msg text,created timestamptz DEFAULT clock_timestamp());
END $reset$;
